        let now = Date()
        if let last = lastDownTime, now.timeIntervalSince(last) < 0.5 {
            pendingSingleTimer?.invalidate()
            pendingSingleTimer = nil
            lastDownTime = nil
            onDoubleDown?()
        } else {
            lastDownTime = now
            pendingSingleTimer?.invalidate()
            pendingSingleTimer = Timer.scheduledTimer(withTimeInterval: 0.55, repeats: false) { [weak self] _ in
