                ))
                .gesture(
                    DragGesture(minimumDistance: 40)
                        .onEnded { value in
                            if value.translation.width < -40 {
                                cycleDirection = .trailing
                                withAnimation(.spring(response: 0.35, dampingFraction: 0.8)) {
                                    appState.cycleSurface()
                                }
                            } else if value.translation.width > 40 {
                                cycleDirection = .leading
                                withAnimation(.spring(response: 0.35, dampingFraction: 0.8)) {
                                    appState.cycleSurfaceBackward()
                                }
                            }
                        }
                )
            }

            // Secondary tiles
            if hasSidebar {
                ScrollView(.vertical, showsIndicators: false) {
                    VStack(spacing: 6) {
                        ForEach(secondarySurfaces) { surface in
                            PaneCardView(
                                title: surface.title,
                                isFocused: false,
                                hasNotification: appState.hasNotification(for: surface),
                                isTranscribing: false,
                                transcript: ""
                            )

import SwiftUI

struct PaneCardView: View {
    let title: String
    let isFocused: Bool
    let hasNotification: Bool
    let isTranscribing: Bool
    let transcript: String

    @State private var notificationPulse = false

    var body: some View {
        ZStack {
            // Glass background
            RoundedRectangle(cornerRadius: 16)
                .fill(.ultraThinMaterial.opacity(isFocused ? 0.4 : 0.2))
                .environment(\.colorScheme, .dark)

            // Notification pulse ring
            if hasNotification {
                RoundedRectangle(cornerRadius: 16)
                    .stroke(Color.orange, lineWidth: 2.5)
                    .opacity(notificationPulse ? 0.4 : 1.0)
                    .animation(
                        .easeInOut(duration: 1.2).repeatForever(autoreverses: true),
                        value: notificationPulse
                    )
                    .onAppear { notificationPulse = true }
                    .onDisappear { notificationPulse = false }
            }

            // Focus glow border
            RoundedRectangle(cornerRadius: 16)
                .stroke(borderColor, lineWidth: isFocused ? 1.5 : 0.5)

            // Content
            VStack(alignment: .leading, spacing: 0) {
                // Traffic lights
                HStack(spacing: 5) {
                    Circle().fill(Color(red: 1, green: 0.37, blue: 0.34)).frame(width: 6, height: 6)
                    Circle().fill(Color(red: 1, green: 0.73, blue: 0.1)).frame(width: 6, height: 6)
                    Circle().fill(Color(red: 0.19, green: 0.8, blue: 0.39)).frame(width: 6, height: 6)
                }
                .padding(.leading, 10)
                .padding(.top, 10)

                Spacer()

                // Transcript or title
                if isTranscribing && !transcript.isEmpty {
                    Text(transcript)
                        .font(.system(size: 11, weight: .regular, design: .monospaced))
                        .foregroundColor(.white)
                        .lineLimit(3)
                        .padding(.horizontal, 10)
                } else if !title.isEmpty {
                    Text(title)
                        .font(.system(size: 11, weight: .medium, design: .monospaced))
                        .foregroundColor(isFocused ? .white : .white.opacity(0.4))
                        .lineLimit(1)
                        .truncationMode(.middle)
                        .padding(.horizontal, 10)
                }

                Spacer().frame(height: 10)
            }

            // Recording indicator
            if isTranscribing {
                VStack {
                    HStack {
                        Spacer()
                        Circle()
                            .fill(Color.red)
                            .frame(width: 8, height: 8)
                            .shadow(color: .red.opacity(0.6), radius: 4)
