                    }
                    Spacer()
                }
            }
        }
        // Focused glow shadow
        .shadow(color: isFocused ? .white.opacity(0.08) : .clear, radius: 12)
        // Recording tint
        .overlay(
            RoundedRectangle(cornerRadius: 16)
                .fill(isTranscribing ? Color.red.opacity(0.05) : .clear)
