import SwiftUI
import AudioToolbox

// MARK: - Quick action model

struct QuickAction: Identifiable {
    let id = UUID()
    let label: String
    let icon: String
    let section: String
    let action: () -> Void
}

struct WorkspaceLayoutView: View {
    @EnvironmentObject var appState: AppState
    @AppStorage("autoSubmitSpeech") private var autoSubmitSpeech = true
    @StateObject private var volumeHandler = VolumeButtonHandler()
    @StateObject private var speechManager = SpeechInputManager()
    @State private var lastNotificationCount = 0
    @State private var cycleDirection: Edge = .trailing

    // Quick action menu state
    @State private var showQuickActions = false
    @State private var selectedActionIndex = 0

    var body: some View {
        ZStack {
            // Background with subtle center glow
            Color.black.ignoresSafeArea()
            RadialGradient(
                colors: [Color.white.opacity(0.03), Color.clear],
                center: .center,
                startRadius: 50,
                endRadius: 400
            )
            .ignoresSafeArea()

            VStack(spacing: 0) {
                if appState.surfaces.isEmpty {
                    emptyState
                } else {
                    surfaceLayout
                }

                workspaceBar
                    .padding(.bottom, 4)
            }

            // Quick action overlay
            if showQuickActions {
                quickActionOverlay
            }
        }
        .animation(.spring(response: 0.25, dampingFraction: 0.85), value: showQuickActions)
        .onChange(of: appState.notifications.count) { oldCount, newCount in
            if newCount > oldCount {
                AudioServicesPlaySystemSound(1007)
                AudioServicesPlaySystemSound(kSystemSoundID_Vibrate)
            }
            lastNotificationCount = newCount
        }
        .onAppear {
            appState.refreshSurfaces()
            speechManager.requestPermissions()
            wireVolumeCallbacks()
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) {
                volumeHandler.start()
            }
        }
        .onDisappear {}
    }

    // MARK: - Quick actions

    private var actions: [QuickAction] {
        guard let surface = focusedSurface else { return [] }
        let sid = surface.id
        return [
            QuickAction(label: "Enter", icon: "return", section: "Input") {
                appState.sendKey("enter", to: sid)
            },
            QuickAction(label: "Ctrl+C", icon: "xmark.circle", section: "Input") {
                appState.sendKey("ctrl+c", to: sid)
            },
            QuickAction(label: "Ctrl+D", icon: "eject", section: "Input") {
                appState.sendKey("ctrl+d", to: sid)
            },
            QuickAction(label: "Ctrl+Z", icon: "pause.circle", section: "Input") {
                appState.sendKey("ctrl+z", to: sid)
            },
            QuickAction(label: "Clear", icon: "trash", section: "Input") {
                appState.sendKey("ctrl+l", to: sid)
            },
            QuickAction(label: "Split Pane", icon: "rectangle.split.2x1", section: "Terminal") {
                appState.sendKey("cmd+d", to: sid)
            },
            QuickAction(label: "Split Horiz", icon: "rectangle.split.1x2", section: "Terminal") {
                appState.sendKey("cmd+shift+d", to: sid)
            },
            QuickAction(label: "New Tab", icon: "plus.rectangle", section: "Terminal") {
                appState.sendKey("cmd+t", to: sid)
            },
            QuickAction(label: "Close Pane", icon: "xmark.rectangle", section: "Terminal") {
                appState.sendKey("cmd+w", to: sid)
            },
            QuickAction(label: "New Workspace", icon: "square.grid.2x2", section: "Workspace") {
                appState.createWorkspace()
            },
        ]
    }

    private func openQuickActions() {
        guard focusedSurface != nil else { return }
        selectedActionIndex = 0
        showQuickActions = true
        UIImpactFeedbackGenerator(style: .medium).impactOccurred()
    }

    private func dismissQuickActions() {
        showQuickActions = false
    }

    private func executeSelectedAction() {
        let list = actions
        guard list.indices.contains(selectedActionIndex) else { return }
        list[selectedActionIndex].action()
        UIImpactFeedbackGenerator(style: .light).impactOccurred()
        dismissQuickActions()
        // Refresh after a short delay to pick up new surfaces/panes
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) {
            appState.refreshSurfaces()
        }
    }

    private func cycleAction() {
        let list = actions
        guard !list.isEmpty else { return }
        selectedActionIndex = (selectedActionIndex + 1) % list.count
        UISelectionFeedbackGenerator().selectionChanged()
    }

    private var quickActionOverlay: some View {
        ZStack {
            // Dimmed background — tap to cancel
            Color.black.opacity(0.6)
                .ignoresSafeArea()
                .onTapGesture { dismissQuickActions() }

            // Action list
            HStack(spacing: 16) {
                // Left: grouped actions
                VStack(alignment: .leading, spacing: 2) {
                    let grouped = Dictionary(grouping: actions.enumerated().map { ($0.offset, $0.element) }, by: { $0.1.section })
                    let sectionOrder = ["Input", "Terminal", "Workspace"]

                    ForEach(sectionOrder, id: \.self) { section in
                        if let items = grouped[section] {
                            Text(section.uppercased())
                                .font(.system(size: 9, weight: .bold, design: .monospaced))
                                .foregroundStyle(.white.opacity(0.3))
                                .padding(.leading, 12)
                                .padding(.top, items == grouped[sectionOrder.first ?? ""] ? 0 : 6)

                            ForEach(items, id: \.0) { index, action in
                                let isSelected = index == selectedActionIndex

                                Button {
                                    selectedActionIndex = index
                                    executeSelectedAction()
                                } label: {
                                    HStack(spacing: 8) {
                                        Image(systemName: action.icon)
                                            .font(.system(size: 11))
                                            .frame(width: 16)
                                        Text(action.label)
                                            .font(.system(size: 12, weight: .medium, design: .monospaced))
                                        Spacer()
                                    }
                                    .foregroundStyle(isSelected ? .white : .white.opacity(0.5))
                                    .padding(.horizontal, 12)
                                    .padding(.vertical, 7)
                                    .background(
                                        RoundedRectangle(cornerRadius: 6)
                                            .fill(isSelected ? Color.white.opacity(0.15) : .clear)
                                    )
                                }
                                .buttonStyle(.plain)
                            }
                        }
                    }
                }
                .frame(width: 200)
                .padding(.vertical, 12)
                .background(
                    RoundedRectangle(cornerRadius: 12)
                        .fill(.ultraThinMaterial)
                        .environment(\.colorScheme, .dark)
                )

                // Right: hint
                VStack(spacing: 8) {
                    HStack(spacing: 4) {
                        Image(systemName: "speaker.wave.1")
                            .font(.system(size: 10))
                        Text("VOL-")
                            .font(.system(size: 10, weight: .bold, design: .monospaced))
                        Text("cycle")
                            .font(.system(size: 10, design: .monospaced))
                    }
                    HStack(spacing: 4) {
                        Image(systemName: "speaker.wave.3")
                            .font(.system(size: 10))
                        Text("VOL+")
                            .font(.system(size: 10, weight: .bold, design: .monospaced))
                        Text("confirm")
                            .font(.system(size: 10, design: .monospaced))
                    }
                    HStack(spacing: 4) {
                        Image(systemName: "hand.tap")
                            .font(.system(size: 10))
                        Text("TAP")
                            .font(.system(size: 10, weight: .bold, design: .monospaced))
                        Text("cancel")
                            .font(.system(size: 10, design: .monospaced))
                    }
                }
                .foregroundStyle(.white.opacity(0.3))
                .padding(12)
            }
        }
        .transition(.opacity)
    }

    // MARK: - Surface layout

    private var focusedSurface: Surface? {
        appState.surfaces.first(where: { $0.id == appState.focusedSurfaceID })
            ?? appState.surfaces.first
    }

    private var secondarySurfaces: [Surface] {
        guard let focused = focusedSurface else { return [] }
        return appState.surfaces.filter { $0.id != focused.id }
    }

    private var surfaceLayout: some View {
        GeometryReader { geo in
            let hasSidebar = secondarySurfaces.count > 0
            let mainWidth = hasSidebar ? geo.size.width * 0.65 : geo.size.width
            let sideWidth = geo.size.width * 0.35

            HStack(spacing: 8) {
                // Focused surface — large card
                if let surface = focusedSurface {
                    PaneCardView(
                        title: surface.title,
                        isFocused: true,
                        hasNotification: appState.hasNotification(for: surface),
                        isTranscribing: speechManager.isRecording,
                        transcript: speechManager.transcript
                    )
                    .id(surface.id)
                    .frame(width: mainWidth - (hasSidebar ? 4 : 16))
                    .transition(.asymmetric(
                        insertion: .move(edge: cycleDirection).combined(with: .opacity),
                        removal: .move(edge: cycleDirection == .trailing ? .leading : .trailing).combined(with: .opacity)
                    ))
                    .onLongPressGesture { openQuickActions() }
                    .simultaneousGesture(
                        DragGesture(minimumDistance: 40)
                            .onEnded { value in
                                guard !showQuickActions else { return }
                                if value.translation.width < -40 {
                                    cycleDirection = .trailing
                                    withAnimation(.spring(response: 0.35, dampingFraction: 0.8)) {
                                        appState.cycleSurface()
                                    }
                                } else if value.translation.width > 40 {
                                    cycleDirection = .leading
                                    withAnimation(.spring(response: 0.35, dampingFraction: 0.8)) {
                                        appState.cycleSurfaceBackward()
                                    }
                                }
                            }
                    )
                }

                // Secondary tiles
                if hasSidebar {
                    ScrollView(.vertical, showsIndicators: false) {
                        VStack(spacing: 6) {
                            ForEach(secondarySurfaces) { surface in
                                PaneCardView(
                                    title: surface.title,
                                    isFocused: false,
                                    hasNotification: appState.hasNotification(for: surface),
                                    isTranscribing: false,
                                    transcript: ""
                                )
                                .frame(height: tileHeight(for: secondarySurfaces.count, in: geo.size.height))
                                .onTapGesture {
                                    cycleDirection = .trailing
                                    withAnimation(.spring(response: 0.35, dampingFraction: 0.8)) {
                                        appState.focusSurface(surface.id)
                                    }
                                }
                                .gesture(
                                    DragGesture(minimumDistance: 30)
                                        .onEnded { value in
                                            if value.translation.height < -30 {
                                                withAnimation(.spring(response: 0.35, dampingFraction: 0.8)) {
                                                    appState.focusSurface(surface.id)
                                                }
                                            }
                                        }
                                )
                            }
                        }
                    }
                    .frame(width: sideWidth - 4)
                }
            }
            .padding(.horizontal, 12)
            .padding(.top, 8)
        }
    }

    private func tileHeight(for count: Int, in totalHeight: CGFloat) -> CGFloat {
        let available = totalHeight - 52
        let spacing = CGFloat(max(0, count - 1)) * 6
        return max(60, (available - spacing) / CGFloat(count))
    }

    // MARK: - Empty state

    private var emptyState: some View {
        VStack(spacing: 12) {
            Image(systemName: "square.split.2x1")
                .font(.system(size: 32, weight: .thin))
                .foregroundStyle(.white.opacity(0.2))
            Text("No surfaces")
                .font(.system(size: 14, weight: .medium))
                .foregroundStyle(.white.opacity(0.3))
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
    }

    // MARK: - Workspace bar

    private var workspaceBar: some View {
        HStack(spacing: 0) {
            statusDot
                .padding(.leading, 16)
                .padding(.trailing, 12)

            workspacePills

            HStack(spacing: 10) {
                if speechManager.isRecording {
                    Circle()
                        .fill(Color.red)
                        .frame(width: 8, height: 8)
                        .shadow(color: .red.opacity(0.6), radius: 4)
                    Text("REC")
                        .font(.system(size: 10, weight: .bold, design: .monospaced))
                        .foregroundStyle(.red)
                }

                Button {
                    appState.refreshSurfaces()
                } label: {
                    Image(systemName: "arrow.clockwise")
                        .font(.system(size: 12))
                        .foregroundStyle(.white.opacity(0.4))
                }
            }
            .padding(.trailing, 16)
            .padding(.leading, 12)
        }
        .frame(height: 36)
    }

    // MARK: - Workspace pills

    private func workspaceLabel(for ws: Workspace, at index: Int) -> String {
        let name = ws.name
        if name == ws.id || name.allSatisfy({ $0.isHexDigit || $0 == "-" }) {
            return "Workspace \(index + 1)"
        }
