                } label: {
                    Image(systemName: "arrow.clockwise")
                        .font(.system(size: 12))
                        .foregroundStyle(.white.opacity(0.4))
                }
            }
            .padding(.trailing, 16)
            .padding(.leading, 12)
        }
        .frame(height: 36)
    }

