140	// runDaemon starts the bridge in daemon mode with reconnect loop.
141	func runDaemon(dir string, cfg config) {
142		if cfg.SocketPassword == "" {
143			// Probe the socket; if it responds with auth_required, fail fast
144			client := socket.NewClient(cfg.SocketPath, "")
145			if err := client.Connect(); err != nil {
146				// Connection error — could be socket not running, fail with helpful message
147				log.Fatalf("cannot connect to cmux socket at %s: %v\nRun with --pair to configure", cfg.SocketPath, err)
148			}
149			_, probeErr := client.Send("system.ping", nil)
150			client.Close()
151			if probeErr != nil && isAuthRequired(probeErr) {
152				log.Fatalf("cmux socket requires a password but none is configured.\nRun with --pair to configure the password.")
153			}
154		}
155	
156		token, err := pair.LoadOrCreateToken(dir)
157		if err != nil {
158			log.Fatalf("token: %v", err)
159		}
160	
161		log.Printf("cmux-bridge %s starting on port %d", ws.BridgeVersion(), cfg.BridgePort)
162		log.Printf("socket: %s", cfg.SocketPath)
163	
164		ctx, cancel := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
165		defer cancel()
166	
167		cmuxClient := socket.NewClient(cfg.SocketPath, cfg.SocketPassword)
168		cmuxConnectedFlag := false
169	
170		poll := poller.New(cmuxClient, time.Duration(cfg.PollIntervalMs)*time.Millisecond)
171	
172		stopPoller := make(chan struct{})
173		go func() {
174			<-ctx.Done()
175			close(stopPoller)
176		}()
177		go poll.Run(stopPoller)
178	
179		// Reconnect loop — also broadcasts cmux.connected / cmux.disconnected to WS clients.
180		go func() {
181			backoff := time.Second
182			for {
183				select {
184				case <-ctx.Done():
185					return
186				default:
187				}
188	
189				err := cmuxClient.Connect()
190				if err != nil {
191					log.Printf("cmux: connect error: %v (retry in %s)", err, backoff)
192					if cmuxConnectedFlag {
193						cmuxConnectedFlag = false
194						poll.Broadcast(poller.Event{
195							Type: "cmux.disconnected",
196							Data: map[string]any{"reason": "socket_unavailable"},
197						})
198					}
199					select {
200					case <-ctx.Done():
201						return
202					case <-time.After(backoff):
203					}
204					if backoff < 30*time.Second {
205						backoff *= 2
206					}
207					continue
208				}
209	
210				log.Printf("cmux: connected")
211				backoff = time.Second
212				cmuxConnectedFlag = true
213				poll.Broadcast(poller.Event{
214					Type: "cmux.connected",
215					Data: map[string]any{"bridge_version": ws.BridgeVersion()},
216				})
217	
218				// Wait until connection drops (Send will return error)
219			pingLoop:
220				for {
221					select {
222					case <-ctx.Done():
223						return
224					case <-time.After(5 * time.Second):
225						if _, err := cmuxClient.Send("system.ping", nil); err != nil {
226							log.Printf("cmux: connection lost: %v", err)
227							cmuxConnectedFlag = false
228							poll.Broadcast(poller.Event{
229								Type: "cmux.disconnected",
230								Data: map[string]any{"reason": "socket_unavailable"},
231							})
232							break pingLoop
233						}
234					}
235				}
236			}
237		}()
238	
239		// Start mDNS advertisement
240		stopMDNS, err := mdns.Advertise(cfg.BridgePort)
241		if err != nil {
242			log.Printf("mdns: %v (continuing without mDNS)", err)
243		} else {
244			defer stopMDNS()
245		}
246	
247		// Start WebSocket server
248		server := ws.NewServer(token, poll, cmuxClient, func() bool { return cmuxConnectedFlag })
249		addr := fmt.Sprintf(":%d", cfg.BridgePort)
250		log.Printf("ws: listening on %s", addr)
251		if err := server.ListenAndServe(ctx, addr); err != nil {
252			log.Fatalf("ws server: %v", err)
253		}
254	}
255	
256	func isAuthRequired(err error) bool {
257		if err == nil {
258			return false
259		}
260		s := err.Error()
261		return strings.Contains(s, "auth_required") || strings.Contains(s, "Authentication required")
262	}
